/*
 * A157451  Number generated by regarding the numbers in row n of A139038 as
 *          digits of a base n number.
 * https://oeis.org/A157451
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = FromDigits[ Table[ Min[1 + Floor[m/2], 1 +
 *            Floor[(n-1-m)/2]], {m,0,n-1} ], n]
 * Range:     u8 n <= 4, u16 n <= 6, u32 n <= 10, u64 n <= 16, u128 n <= 18,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The digits are taken in order m = 0 .. n‑1; base = n. */

#include <stdint.h>

/* Return the nth term of OEIS sequence A157451.  The index n is 1‑based. */
seq_t a(idx_t n)
{
    if (n == 0)   /* offset is 1; value for n=0 is irrelevant */
        return 0;

    seq_t result = 0;
    const seq_t base = (seq_t)n;          /* base is n */

    for (idx_t m = 0; m < n; ++m) {
        /* Compute the digit d = min(1+⌊m/2⌋, 1+⌊(n-1-m)/2⌋) */
        idx_t left  = 1 + (m / 2);
        idx_t right = 1 + ((n - 1 - m) / 2);
        idx_t d = (left < right) ? left : right;   /* d fits in idx_t */

        result = result * base + (seq_t)d;
    }
    return result;
}
